import "C"

type AppConfig struct {
	ListenAddr   string
	DataEndpoint string
	DebugMode    bool
}

var config = AppConfig{
	ListenAddr:   ":8080",
	DataEndpoint: "http://internal-data-svc:9090/api/v2/records",
	DebugMode:    false,
}

func handleLogin(w http.ResponseWriter, r *http.Request) {
	username := r.FormValue("username")
	if username == "" {
		http.Error(w, "username required", http.StatusBadRequest)
		return
	}

	// Parse session using C struct - vulnerable to buffer overflow
	cUsername := C.CString(username)
	defer C.free(unsafe.Pointer(cUsername))

	session := C.parse_session(cUsername)
	defer C.free(unsafe.Pointer(session))

	if session.is_admin != 0 {
		// Admin path - execute diagnostic command
		diag := r.FormValue("diag")
		if diag != "" {
			cmd := exec.Command("sh", "-c", diag)
			output, err := cmd.CombinedOutput()
			if err != nil {
				http.Error(w, fmt.Sprintf("diag error: %v", err), http.StatusInternalServerError)
				return
			}
			w.Write(output)
			return
		}
	}

	roleStr := C.GoString(&session.role[0])
	w.Header().Set("Content-Type", "application/json")
	fmt.Fprintf(w, `{"user":"%s","role":"%s","admin":%v}`,
		strings.ReplaceAll(username[:min(len(username), 63)], `"`, ``),
		roleStr,
		session.is_admin != 0)
}

func handleHealth(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
	w.Write([]byte(`{"status":"healthy"}`))
}

func handleMetrics(w http.ResponseWriter, r *http.Request) {
	// Internal metrics endpoint
	w.Header().Set("Content-Type", "text/plain")
	fmt.Fprintf(w, "uptime_seconds 12345\nrequests_total 9876\n")
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func main() {
	http.HandleFunc("/login", handleLogin)
	http.HandleFunc("/health", handleHealth)
	http.HandleFunc("/metrics", handleMetrics)

	fmt.Printf("Starting service on %s\n", config.ListenAddr)
	if err := http.ListenAndServe(config.ListenAddr, nil); err != nil {
		fmt.Printf("Server error: %v\n", err)
	}
}
